  ('4ae53ad5-07ef-4821-a14b-a296c57d17ab', 'en', 'Soen', 'swedish progressive metal band', 'Soen is a Swedish progressive metal band formed in 2010. The group consists of vocalist Joel Ekelöf, guitarist Cody Lee Ford, bassist Stefan Stenberg, drummer Martin Lopez and keyboardist Lars Åhlund.', array[]::text[], 'https://en.wikipedia.org/wiki/Soen'),
