  ('a0cca423-c2ae-44df-a289-5ad5d65a24d8', 'en', 'Dan + Shay', 'american country duo', 'Dan + Shay is an American country music duo composed of vocalists and songwriters Dan Smyers and Shay Mooney. They are signed to Warner Records Nashville and have released six albums, Where It All Began, Obsessed, Dan + Shay, Good Things, Bigger Houses and It''s Officially Christmas: The Double Album.', array[]::text[], 'https://en.wikipedia.org/wiki/Dan_%2B_Shay'),
