  ('764e68b0-75d1-4500-8b6a-957bfbc4d712', 'en', 'Toploader', 'english rock band', 'Toploader are an English rock band from Eastbourne, East Sussex, formed in 1997, with over two million album sales and several top-20 hits both home and abroad. Their debut album, Onka''s Big Moka, sold over one million copies and peaked in the top five of the UK Albums Chart, where it remained for six months; it earned them four nominations at the 2001 Brit Awards.', array[]::text[], 'https://en.wikipedia.org/wiki/Toploader'),
  ('764e68b0-75d1-4500-8b6a-957bfbc4d712', 'de', 'Toploader', 'english rock band', 'Toploader are an English rock band from Eastbourne, East Sussex, formed in 1997, with over two million album sales and several top-20 hits both home and abroad. Their debut album, Onka''s Big Moka, sold over one million copies and peaked in the top five of the UK Albums Chart, where it remained for six months; it earned them four nominations at the 2001 Brit Awards.', array[]::text[], 'https://en.wikipedia.org/wiki/Toploader'),
