  ('c80b0e10-741e-435c-862d-60b456c33688', 'en', 'Journey', 'american rock band', 'Journey is an American rock band formed in San Francisco in 1973 by former members of Santana, the Steve Miller Band, and Frumious Bandersnatch. The band as of 2026 consists of Neal Schon on guitars and vocals; Jonathan Cain on keyboards, guitars and vocals; Deen Castronovo on drums and vocals; Arnel Pineda on lead vocals; Jason Derlatka on keyboards and vocals; and Todd Jensen on bass and vocals.', array[]::text[], 'https://en.wikipedia.org/wiki/Journey_(band)'),
