  ('56deb1d7-d33b-49ab-b86d-b097bbe9b9a2', 'en', 'My Chemical Romance', 'american rock band', 'My Chemical Romance is an American rock band from New Jersey. The band''s current lineup consists of lead vocalist Gerard Way, lead guitarist Ray Toro, rhythm guitarist Frank Iero, and bassist Mikey Way.', array[]::text[], 'https://en.wikipedia.org/wiki/My_Chemical_Romance'),
