  ('59dea2ff-dec0-4f09-9ea1-de940bbc10a8', 'en', 'Muse', 'english rock band', 'Muse are an English rock band from Teignmouth, Devon, formed in 1994. The band consists of Matt Bellamy, Chris Wolstenholme, and Dominic Howard.', array[]::text[], 'https://en.wikipedia.org/wiki/Muse_(band)'),
