  ('21892882-8018-4467-8a97-9b0b4e691f5d', 'en', 'Squeeze', 'english rock band', 'Squeeze are an English rock band that came to prominence in the United Kingdom during the new wave period of the late 1970s, and continued recording in the 1980s, 1990s and 2010s. In the UK, their singles "Cool for Cats", "Up the Junction", and "Labelled with Love" were top-ten chart hits.', array[]::text[], 'https://en.wikipedia.org/wiki/Squeeze_(band)'),
  ('21892882-8018-4467-8a97-9b0b4e691f5d', 'de', 'Squeeze', 'english rock band', 'Squeeze are an English rock band that came to prominence in the United Kingdom during the new wave period of the late 1970s, and continued recording in the 1980s, 1990s and 2010s. In the UK, their singles "Cool for Cats", "Up the Junction", and "Labelled with Love" were top-ten chart hits.', array[]::text[], 'https://en.wikipedia.org/wiki/Squeeze_(band)'),
