  ('f9555459-8355-40e4-9423-39c8ad6a2d95', 'en', 'Airbag', 'argentine rock band', 'Airbag is an Argentine hard rock band formed in Buenos Aires in 1999, consisting of three brothers: Patricio Sardelli, Gastón Sardelli, and Guido Sardelli. They have released eight studio albums and two live albums, and tour mostly around Latin America.', array[]::text[], 'https://en.wikipedia.org/wiki/Airbag_(band)'),
