-- 362 previews, 232 abouts. Paste in the Supabase SQL editor, Run. Rows that exist are updated.

on conflict (event_id) do update set track = excluded.track, artist = excluded.artist, preview_url = excluded.preview_url, link = excluded.link, source = excluded.source, made_at = now();

on conflict (event_id, lang) do update set name = excluded.name, kicker = excluded.kicker, who = excluded.who, facts = excluded.facts, source_url = excluded.source_url, made_at = now();
